//! Ordinary generated data only. This executable cannot register a root.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    use std::{fs, io::Write, path::PathBuf};
    use twodrive_cfapi_probe::fixtures::Dataset;
    let mut args = std::env::args_os().skip(1);
    let first = args
        .next()
        .ok_or("NEW output directory or --png-stdout required")?;
    if args.next().is_some() {
        return Err("unexpected arguments".into());
    }
    if first.as_os_str() == std::ffi::OsStr::new("--png-stdout") {
        // Pure generated bytes. No directory creation or filesystem reads;
        // useful where the host cannot establish an unmanaged CFAPI root.
        std::io::stdout()
            .lock()
            .write_all(&Dataset::VisualV1.bytes(1))?;
        return Ok(());
    }
    let out = PathBuf::from(first);
    fs::create_dir(&out)?;
    let dataset = Dataset::VisualV1;
    for folder in dataset.directories() {
        fs::create_dir(out.join(folder.relative_path))?;
    }
    for (index, file) in dataset.files().into_iter().enumerate() {
        let mut output = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(out.join(file.relative_path))?;
        output.write_all(&dataset.bytes(index))?;
        output.sync_all()?;
    }
    let manifest = serde_json::json!({"schema_version":1,"dataset":dataset,"directories":dataset.directories(),"files":dataset.files(),"registered":false});
    let mut sidecar = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(out.with_extension("dataset.json"))?;
    sidecar.write_all(&serde_json::to_vec_pretty(&manifest)?)?;
    sidecar.sync_all()?;
    println!("exported3 x65536-byte ordinary files,1 directory; no registration");
    Ok(())
}
